import React from 'react';
import * as flags from '..';
import type { FlagIconType } from '../../types';

interface FlagTypeDemo extends FlagIconType {
  flagName: keyof typeof flags;
}

const Demo = ({ flagName, size = 'lg' }: FlagTypeDemo) => {
  const Flag = flags[flagName];
  return <Flag size={size} />;
};

export default Demo;
